import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir, readFile, writeFile } from 'node:fs/promises';

import { ACTIVE_CLASSIC_APPARATUS_EXPORTS } from './classic-kit-active-config.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');

const files = [
  path.join(repoRoot, 'lib/apparatus/core/anchors.js'),
  path.join(repoRoot, 'lib/apparatus/core/liquids.js'),
  path.join(repoRoot, 'lib/apparatus/core/validation.js'),
  path.join(repoRoot, 'lib/apparatus/chemicals.js'),
  path.join(repoRoot, 'lib/apparatus/solids.js'),
  path.join(repoRoot, 'lib/apparatus/presets/shared.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-showcase.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-test-tube.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-widemouth-jar.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-solid-reagent-jar.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-copper-piece.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-reagent-bottle.js'),
  path.join(repoRoot, 'lib/apparatus/presets/zinc-granules.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-erlenmeyer.js'),
  path.join(repoRoot, 'lib/apparatus/presets/classic-moist-paper.js'),
];

const outputPath = path.join(repoRoot, 'templates/classic-apparatus-inline-snippet.js');

function stripModuleSyntax(source) {
  return source
    .replace(/^import[\s\S]*?;\n?/gm, '')
    .replace(/^export\s*\{[^}]*\}\s*from\s*['"][^'"]+['"];?\n?/gm, '')
    .replace(/^export \{[\s\S]*?\};?$/gm, '')
    .replace(/^export /gm, '')
    .trim();
}

async function buildInlineSnippet() {
  const sections = await Promise.all(files.map((filePath) => readFile(filePath, 'utf8')));
  const body = sections.map(stripModuleSyntax).join('\n\n');
  const snippet = `// Generated by scripts/build-classic-apparatus-inline-bundle.mjs
// Paste this inside a <script type="module"> block after importing THREE.

${body}

const ChemApparatusLib = {
  ${ACTIVE_CLASSIC_APPARATUS_EXPORTS.join(',\n  ')},
};

globalThis.ChemApparatusLib = ChemApparatusLib;
`;

  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${snippet}\n`, 'utf8');
  return outputPath;
}

const builtPath = await buildInlineSnippet();
console.log(`Built classic apparatus inline snippet: ${builtPath}`);
